use std::boxed::Box;

pub fn new_node(key: i32) -> Box<Node> {
    Box::new(Node {
        key,
        left: None,
        right: None,
        height: 1,
    })
}

pub fn min_value_node(node: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut current = node;
    while let Some(ref left) = current.as_ref().and_then(|n| n.left.as_ref()) {
        current = Some(left.clone());
    }
    current
}

pub fn pre_order(root: &Option<Box<Node>>) {
    if let Some(node) = root {
        print!("{} ", node.key);
        pre_order(&node.left);
        pre_order(&node.right);
    }
}

pub fn right_rotate(y: Option<Box<Node>>) -> Option<Box<Node>> {
    if let Some(mut y_node) = y {
        if let Some(mut x_node) = y_node.left.take() {
            let t2 = x_node.right.take();
            y_node.left = t2;
            y_node.height = max(height(y_node.left.as_ref()), height(y_node.right.as_ref())) + 1;
            x_node.right = Some(y_node);
            x_node.height = max(height(x_node.left.as_ref()), height(x_node.right.as_ref())) + 1;
            return Some(x_node);
        }
    }
    None
}

pub fn left_rotate(x: Box<Node>) -> Box<Node> {
    let mut y = x.right.unwrap();
    let t2 = y.left.take();
    x.right = t2;
    x.height = max(height(x.left.as_ref()), height(x.right.as_ref())) + 1;
    y.left = Some(x);
    y.height = max(height(y.left.as_ref()), height(y.right.as_ref())) + 1;
    y
}

pub fn get_balance(node: Option<&Box<Node>>) -> i32 {
    match node {
        None => 0,
        Some(n) => height(n.left.as_ref()) - height(n.right.as_ref()),
    }
}

pub fn insert(node: Option<Box<Node>>, key: i32) -> Option<Box<Node>> {
    if node.is_none() {
        return Some(new_node(key));
    }

    let mut node = node.unwrap();

    if key < node.key {
        node.left = insert(node.left, key);
    } else if key > node.key {
        node.right = insert(node.right, key);
    } else {
        return Some(node);
    }

    node.height = 1 + max(height(node.left.as_ref()), height(node.right.as_ref()));

    let balance = get_balance(Some(&node));

    if balance > 1 && key < node.left.as_ref().unwrap().key {
        return right_rotate(Some(node));
    }

    if balance < -1 && key > node.right.as_ref().unwrap().key {
        return Some(left_rotate(node));
    }

    if balance > 1 && key > node.left.as_ref().unwrap().key {
        node.left = Some(left_rotate(node.left.unwrap()));
        return right_rotate(Some(node));
    }

    if balance < -1 && key < node.right.as_ref().unwrap().key {
        node.right = right_rotate(node.right);
        return Some(left_rotate(node));
    }

    Some(node)
}

pub fn delete_node(root: Option<Box<Node>>, key: i32) -> Option<Box<Node>> {
    let mut root = root;

    if root.is_none() {
        return root;
    }

    if key < root.as_ref().unwrap().key {
        root.as_mut().unwrap().left = delete_node(root.as_mut().unwrap().left.take(), key);
    } else if key > root.as_ref().unwrap().key {
        root.as_mut().unwrap().right = delete_node(root.as_mut().unwrap().right.take(), key);
    } else {
        if root.as_ref().unwrap().left.is_none() || root.as_ref().unwrap().right.is_none() {
            let temp = if root.as_ref().unwrap().left.is_some() {
                root.as_mut().unwrap().left.take()
            } else {
                root.as_mut().unwrap().right.take()
            };

            if temp.is_none() {
                root = None;
            } else {
                *root.as_mut().unwrap() = *temp.unwrap();
            }
        } else {
            let temp = min_value_node(root.as_mut().unwrap().right.take());
            root.as_mut().unwrap().key = temp.as_ref().unwrap().key;
            root.as_mut().unwrap().right = delete_node(root.as_mut().unwrap().right.take(), temp.unwrap().key);
        }
    }

    if root.is_none() {
        return root;
    }

    root.as_mut().unwrap().height = 1 + max(
        height(root.as_ref().unwrap().left.as_ref()),
        height(root.as_ref().unwrap().right.as_ref()),
    );

    let balance = get_balance(root.as_ref());

    if balance > 1 && get_balance(root.as_ref().unwrap().left.as_ref()) >= 0 {
        return right_rotate(root);
    }

    if balance > 1 && get_balance(root.as_ref().unwrap().left.as_ref()) < 0 {
        root.as_mut().unwrap().left = Some(left_rotate(root.as_mut().unwrap().left.take().unwrap()));
        return right_rotate(root);
    }

    if balance < -1 && get_balance(root.as_ref().unwrap().right.as_ref()) <= 0 {
        return Some(left_rotate(root.unwrap()));
    }

    if balance < -1 && get_balance(root.as_ref().unwrap().right.as_ref()) > 0 {
        root.as_mut().unwrap().right = right_rotate(root.as_mut().unwrap().right.take());
        return Some(left_rotate(root.unwrap()));
    }

    root
}

pub fn main() {
    let mut root: Option<Box<Node>> = None;
    root = insert(root, 9);
    root = insert(root, 5);
    root = insert(root, 10);
    root = insert(root, 0);
    root = insert(root, 6);
    root = insert(root, 11);
    root = insert(root, -1);
    root = insert(root, 1);
    root = insert(root, 2);
    println!("Preorder traversal of the constructed AVL tree is");
    pre_order(&root);
    root = delete_node(root, 10);
    println!("\nPreorder traversal after deletion of 10");
    pre_order(&root);
}
